    /**
     * Get Agent Conversation Timeline.
     *
     * One conversation as the agent handled it, oldest first: the messages (plain text,
     * customer-visible messages only: no internal notes or system events) and every turn of this agent
     * in it (same shape as /turns), so each customer message can be read next to the agent's
     * reasoning, sources, tools and the reply it sent or the hand-off.
     *
     * messages[].turn_id links a message to the turn it triggered (inbound) or that sent it
     * (sender_kind agent_bot). The window starts context_before messages before the agent's first turn
     * and ends up to 20 messages after its last turn; at most 300 messages and 200 turns are returned
     * (truncated is then true).
     *
     * Returns 404 when the conversation does not exist, the agent has no turns in it, or the caller
     * cannot open it in the inbox.
     *
     * Scopes: automation:read, messages:read.
     *
     * @param  ?int  $contextBefore  Messages shown before the agent's first turn in this conversation
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/get_agent_conversation_timeline_api_v1_automation_agents__agent_id__conversations__conversation_id__timeline_get
     */
    public function getConversationTimeline(
        string $agentId,
        string $conversationId,
        ?int $contextBefore = null,
    ): AgentConversationTimeline {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/agents/'.Payload::segment($agentId).'/conversations/'.Payload::segment($conversationId).'/timeline',
            query: Payload::query(['context_before' => $contextBefore]),
        ));

        return AgentConversationTimeline::fromArray($response->data());
    }

    /**
     * Discard Agent Draft.
     *
     * Discard the draft; returns the live config as the editor document.
     *
     * With base_revision: if the agent changed since and there is a draft that differs from the live
     * config, 409 draft_conflict (same body as PUT /agents/{id}/draft) and nothing is discarded.
     *
     * Scopes: automation:update.
     *
     * @param  ?int  $baseRevision  Revision the caller last saw; 409 draft_conflict when the draft changed since
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/discard_agent_draft_api_v1_automation_agents__agent_id__draft_delete
     */
    public function discardDraft(string $agentId, ?int $baseRevision = null): AgentDraft
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/automation/agents/'.Payload::segment($agentId).'/draft',
            query: Payload::query(['base_revision' => $baseRevision]),
        ));

        return AgentDraft::fromArray($response->data());
    }

    /**
     * Get Agent Draft.
     *
     * The editor document: the saved draft (rebased onto the current live config) or, without a draft,
     * the live config. has_unpublished_changes, a per-section changes summary, the publish validation
     * and the editor revision (with revision_updated_at / revision_updated_by) are included. Reading
     * never modifies anything.
     *
     * Scopes: automation:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/get_agent_draft_api_v1_automation_agents__agent_id__draft_get
     */
    public function getDraft(string $agentId): AgentDraft
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/agents/'.Payload::segment($agentId).'/draft',
        ));

        return AgentDraft::fromArray($response->data());
    }

    /**
     * Save Agent Draft.
     *
     * Save (autosave) the agent draft. Fields left out keep their previous draft value; an explicit
     * null resets a nullable field to its default (max_tool_calls, turn_timeout_ms, model_tier and
     * source_footer_mode come back as their concrete default values; a null toggle or a null section /
     * list keeps its value). Validated like the live endpoints (same 422 codes; where it can be
     * determined the 422 also names the document field and editor section, and a located error without
     * its own code is returned as {"code": "invalid_field", "message", "field", "section"}); new
     * knowledge sources / channel rules get server ids. The live agent is not changed until POST
     * /agents/{id}/publish. A draft identical to the live config is cleared. A save that changes
     * nothing is a no-op: it never conflicts and does not move the revision.
     *
     * Concurrent edits: send the revision of the document you edited as base_revision. If the agent
     * changed since and your document differs from the current one, the call returns 409
     * draft_conflict with revision, revision_updated_at, revision_updated_by and the full current
     * editor state in current. Without base_revision the last write wins.
     *
     * Scopes: automation:update.
     *
     * @param  array<string, mixed>  $document
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/save_agent_draft_api_v1_automation_agents__agent_id__draft_put
     */
    public function saveDraft(string $agentId, array $document, ?int $baseRevision = null): AgentDraft
    {
        $response = $this->connector->send(new Request(
            Method::Put,
            '/automation/agents/'.Payload::segment($agentId).'/draft',
            body: Payload::body(['document' => $document, 'base_revision' => $baseRevision]),
        ));

        return AgentDraft::fromArray($response->data());
    }

    /**
     * Get Agent Draft Revision.
