     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/test_agent_api_v1_automation_agents__agent_id__test_post
     */
    public function test(
        string $agentId,
        ?string $message = null,
        ?array $history = null,
        ?array $state = null,
        ?string $skillSlug = null,
        ?string $channelType = null,
        ?array $task = null,
        ?array $attachmentIds = null,
        ?string $config = null,
        ?string $idempotencyKey = null,
    ): AgentTest {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/automation/agents/'.Payload::segment($agentId).'/test',
            body: Payload::body([
                'message' => $message,
                'history' => $history,
                'state' => $state,
                'skill_slug' => $skillSlug,
                'channel_type' => $channelType,
                'task' => $task,
                'attachment_ids' => $attachmentIds,
                'config' => $config,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return AgentTest::fromArray($response->data());
    }

    /**
     * List Agent Turns.
     *
     * Audit log of the agent's turns (newest first). Raw model contents are not returned. contact_name
     * and the conversation / message ids are only returned for conversations the caller can open in
     * the inbox; otherwise they are null and contact_hidden is true (conversation_key still groups the
     * turns of one conversation).
     *
     * Scopes: automation:read.
     *
     * @return Page<AgentTurn>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/list_agent_turns_api_v1_automation_agents__agent_id__turns_get
     */
    public function listTurns(
        string $agentId,
        ?int $page = null,
        ?int $pageSize = null,
        ?string $conversationId = null,
    ): Page {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/agents/'.Payload::segment($agentId).'/turns',
            query: Payload::query([
                'page' => $page,
                'page_size' => $pageSize,
                'conversation_id' => $conversationId,
            ]),
        ));

        return Hydrate::page($response->data(), AgentTurn::fromArray(...), fn (int $page): Page => $this->listTurns(agentId: $agentId, page: $page, pageSize: $pageSize, conversationId: $conversationId));
    }

    /**
     * List Lookup Tables.
     *
     * List the workspace's lookup tables (bounded, single page; at most 20 per workspace). Each item
     * lists the agents (id, name) whose live config or saved draft uses it.
     *
     * Scopes: automation:read.
     *
     * @return Page<LookupTable>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/list_lookup_tables_api_v1_automation_lookup_tables_get
     */
    public function listLookupTables(): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/lookup-tables',
        ));

        return Hydrate::page($response->data(), LookupTable::fromArray(...), null);
    }

    /**
     * Create Lookup Table.
     *
     * Create a lookup table from an uploaded CSV or XLSX file (multipart). The first non-empty row is
     * the header. Without key_columns the server picks suggested search columns. Returns the table
     * with the first rows, parser warnings and the suggested key columns.
     *
     * Scopes: automation:update.
     *
     * @param  FilePart  $file  CSV or XLSX, at most 5 MB
     * @param  ?string  $sheet  XLSX sheet (default: the first)
     * @param  ?string  $keyColumns  JSON list of column names to search by
     * @param  ?string  $returnColumns  JSON list of columns returned (empty = all)
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/create_lookup_table_api_v1_automation_lookup_tables_post
     */
    public function createLookupTable(
        FilePart $file,
        string $name,
        ?string $description = null,
        ?string $sheet = null,
        ?string $keyColumns = null,
        ?string $returnColumns = null,
        ?string $idempotencyKey = null,
    ): LookupTableDetail {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/automation/lookup-tables',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
            multipart: Payload::multipart([
                'file' => $file,
                'name' => $name,
                'description' => $description,
                'sheet' => $sheet,
                'key_columns' => $keyColumns,
                'return_columns' => $returnColumns,
            ]),
        ));

        return LookupTableDetail::fromArray($response->data());
    }

    /**
     * Create Lookup Table From Document.
     *
     * Create a lookup table from a Knowledge Base document: an uploaded CSV / XLSX original, or a
     * document with exactly one Markdown table. 422 document_not_found / document_not_table otherwise.
     *
     * Scopes: automation:update, knowledge_base:read.
     *
     * @param  list<string>|null  $keyColumns
     * @param  list<string>|null  $returnColumns
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/create_lookup_table_from_document_api_v1_automation_lookup_tables_from_document_post
     */
    public function createLookupTableFromDocument(
        string $kbDocumentId,
        string $name,
        ?string $description = null,
        ?array $keyColumns = null,
        ?array $returnColumns = null,
        ?string $idempotencyKey = null,
    ): LookupTableDetail {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/automation/lookup-tables/from-document',
            body: Payload::body([
                'kb_document_id' => $kbDocumentId,
                'name' => $name,
                'description' => $description,
                'key_columns' => $keyColumns,
                'return_columns' => $returnColumns,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return LookupTableDetail::fromArray($response->data());
    }

    /**
     * Delete Lookup Table.
     *
     * Delete a lookup table and all its rows. 409 lookup_table_in_use (with agents: [{id, name}])
     * while any agent's live config or saved draft uses it: remove it from those agents first.
     *
     * Scopes: automation:delete.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/delete_lookup_table_api_v1_automation_lookup_tables__table_id__delete
     */
    public function deleteLookupTable(string $tableId): Delete
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/automation/lookup-tables/'.Payload::segment($tableId),
        ));

        return Delete::fromArray($response->data());
    }

    /**
     * Get Lookup Table.
     *
     * Get one lookup table with its first rows. For a table imported from a Knowledge Base document,
     * preview_rows is empty unless the caller also holds knowledge_base:read.
     *
     * rows of a Knowledge Base document table)
     *
     * Scopes: automation:read, knowledge_base:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/get_lookup_table_api_v1_automation_lookup_tables__table_id__get
     */
    public function getLookupTable(string $tableId): LookupTableDetail
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/lookup-tables/'.Payload::segment($tableId),
        ));

        return LookupTableDetail::fromArray($response->data());
    }

    /**
     * Update Lookup Table.
     *
     * Update name, description, key columns (search by), return columns or the match options. Omitted
     * fields are kept; description: null clears it, return_columns: null or [] returns all columns.
     * Changing the key columns re-indexes the table.
     *
     * Scopes: automation:update.
     *
     * @param  list<string>|null  $keyColumns
     * @param  list<string>|null  $returnColumns
     * @param  array<string, mixed>|null  $settings
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/update_lookup_table_api_v1_automation_lookup_tables__table_id__patch
     */
    public function updateLookupTable(
        string $tableId,
        ?string $name = null,
        ?string $description = null,
        ?array $keyColumns = null,
        ?array $returnColumns = null,
        ?array $settings = null,
        ?string $idempotencyKey = null,
    ): LookupTableDetail {
        $response = $this->connector->send(new Request(
            Method::Patch,
            '/automation/lookup-tables/'.Payload::segment($tableId),
            body: Payload::body([
                'name' => $name,
                'description' => $description,
                'key_columns' => $keyColumns,
                'return_columns' => $returnColumns,
                'settings' => $settings,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return LookupTableDetail::fromArray($response->data());
    }

    /**
     * Replace Lookup Table File.
     *
     * Replace the table's content with a new file (a new version). The swap is atomic and live for
     * every agent immediately. The current key / return columns are kept when all of them still exist;
     * otherwise 422 lookup_table_columns_missing (with missing) unless new ones are sent.
     *
     * Scopes: automation:update.
     *
     * @param  FilePart  $file  CSV or XLSX, at most 5 MB
     * @param  ?string  $keyColumns  JSON list; needed when a key column is gone
     * @param  ?string  $returnColumns  JSON list (empty = all)
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/replace_lookup_table_file_api_v1_automation_lookup_tables__table_id__file_put
     */
    public function replaceLookupTableFile(
        string $tableId,
        FilePart $file,
        ?string $sheet = null,
        ?string $keyColumns = null,
        ?string $returnColumns = null,
    ): LookupTableDetail {
        $response = $this->connector->send(new Request(
            Method::Put,
            '/automation/lookup-tables/'.Payload::segment($tableId).'/file',
            multipart: Payload::multipart([
                'file' => $file,
                'sheet' => $sheet,
                'key_columns' => $keyColumns,
                'return_columns' => $returnColumns,
            ]),
        ));

        return LookupTableDetail::fromArray($response->data());
    }

    /**
     * Test Lookup.
     *
     * Try a lookup: runs the same search the agent runs (exact, then all key terms, then prefix, then
     * fuzzy) and returns every matching row (up to 20). No AI, no credits.
     *
     * table was imported from a Knowledge Base document)
     *
     * Scopes: automation:read, knowledge_base:read.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/test_lookup_api_v1_automation_lookup_tables__table_id__lookup_post
     */
    public function testLookup(
        string $tableId,
        string $query,
        ?string $column = null,
        ?string $idempotencyKey = null,
    ): LookupTest {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/automation/lookup-tables/'.Payload::segment($tableId).'/lookup',
            body: Payload::body(['query' => $query, 'column' => $column]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return LookupTest::fromArray($response->data());
    }

    /**
     * Refresh Lookup Table.
     *
     * Re-import a table created from a Knowledge Base document (new version, live immediately). 422
     * lookup_table_not_kb_document for uploaded tables.
     *
     * Scopes: automation:update, knowledge_base:read.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/refresh_lookup_table_api_v1_automation_lookup_tables__table_id__refresh_post
     */
    public function refreshLookupTable(string $tableId, ?string $idempotencyKey = null): LookupTableDetail
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/automation/lookup-tables/'.Payload::segment($tableId).'/refresh',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return LookupTableDetail::fromArray($response->data());
    }

    /**
     * List Lookup Table Rows.
     *
     * Page through the rows of the active version. Items are {row_index, values: {column: value}} in
     * file order.
     *
     * table was imported from a Knowledge Base document)
     *
     * Scopes: automation:read, knowledge_base:read.
     *
     * @return Page<LookupTableRow>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/AI%20Agents/list_lookup_table_rows_api_v1_automation_lookup_tables__table_id__rows_get
     */
    public function listLookupTableRows(string $tableId, ?int $page = null, ?int $pageSize = null): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/automation/lookup-tables/'.Payload::segment($tableId).'/rows',
            query: Payload::query(['page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), LookupTableRow::fromArray(...), fn (int $page): Page => $this->listLookupTableRows(tableId: $tableId, page: $page, pageSize: $pageSize));
